WITH account_stats AS (SELECT account_id, COUNT(DISTINCT amount) AS unique_txn_types, SORT_ARRAY(COLLECT_SET(txn_type)) AS txn_type_list FROM transactions WHERE is_flagged GROUP BY account_id) SELECT a.id, a.balance, a.status, as.unique_txn_types, as.txn_type_list FROM accounts a INNER JOIN account_stats as ON a.id = as.account_id WHERE as.unique_txn_types >= 8 ORDER BY status, unique_txn_types DESC;
